fn find_first_occurrence(arr: &Vec<i32>, target: i32) -> Option<usize> {
    let mut left = 0;
    let mut right = arr.len();

    // Binary search for the first occurrence of target
    // Invariant: target (if exists) must be at an index >= left and < right
    while left < right {
        let mid = left + (right - left) / 2;
        if arr[mid] < target {
            // target must be to the right of mid
            left = mid + 1;
        } else {
            // arr[mid] >= target, so first occurrence is at mid or to the left
            right = mid;
        }
    }

    // After loop, left == right. Check if arr[left] equals target
    if left < arr.len() && arr[left] == target {
        Some(left)
    } else {
        None
    }
}